-- create "instruments" table
CREATE TABLE "instruments" ("id" uuid NOT NULL, "name" character varying NOT NULL, "family" character varying NOT NULL, "string_count" bigint NULL, "tuning" jsonb NULL, "key_range_lowest" character varying NULL, "key_range_highest" character varying NULL, PRIMARY KEY ("id"));
-- create "diagrams" table
CREATE TABLE "diagrams" ("id" uuid NOT NULL, "name" character varying NOT NULL, "created_at" timestamptz NOT NULL, "instrument_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "diagrams_instruments_instrument" FOREIGN KEY ("instrument_id") REFERENCES "instruments" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- create "diagram_concepts" table
CREATE TABLE "diagram_concepts" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "linked_at" timestamptz NOT NULL, "diagram_id" uuid NOT NULL, "concept_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "diagram_concepts_concepts_concept" FOREIGN KEY ("concept_id") REFERENCES "concepts" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "diagram_concepts_diagrams_diagram" FOREIGN KEY ("diagram_id") REFERENCES "diagrams" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- create index "diagramconcept_diagram_id_concept_id" to table: "diagram_concepts"
CREATE UNIQUE INDEX "diagramconcept_diagram_id_concept_id" ON "diagram_concepts" ("diagram_id", "concept_id");
-- create "diagram_skills" table
CREATE TABLE "diagram_skills" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "linked_at" timestamptz NOT NULL, "diagram_id" uuid NOT NULL, "skill_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "diagram_skills_diagrams_diagram" FOREIGN KEY ("diagram_id") REFERENCES "diagrams" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "diagram_skills_skills_skill" FOREIGN KEY ("skill_id") REFERENCES "skills" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- create index "diagramskill_diagram_id_skill_id" to table: "diagram_skills"
CREATE UNIQUE INDEX "diagramskill_diagram_id_skill_id" ON "diagram_skills" ("diagram_id", "skill_id");
-- create "positions" table
CREATE TABLE "positions" ("id" uuid NOT NULL, "ordinal" bigint NOT NULL, "interval" character varying NOT NULL, "note_name" character varying NOT NULL, "sequence_index" bigint NULL, "string_number" bigint NULL, "fret" bigint NULL, "key" character varying NULL, "diagram_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "positions_diagrams_positions" FOREIGN KEY ("diagram_id") REFERENCES "diagrams" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- create index "position_diagram_id_ordinal" to table: "positions"
CREATE UNIQUE INDEX "position_diagram_id_ordinal" ON "positions" ("diagram_id", "ordinal");
